begin;
do $$begin if current_setting('aroma.test_mode',true) is distinct from 'local-fixture' then raise exception 'Only local fixtures.';end if;end $$;
create schema aroma_complaint_test;
grant usage on schema aroma_complaint_test to anon,authenticated,service_role;
create function aroma_complaint_test.ok(p boolean,label text) returns text language plpgsql as $$begin if p is distinct from true then raise exception 'FAIL: %',label;end if;return 'PASS: '||label;end $$;
create function aroma_complaint_test.error(statement text,state text,label text) returns text language plpgsql as $$declare actual text;begin begin execute statement;exception when others then get stacked diagnostics actual=returned_sqlstate;end;if actual is distinct from state then raise exception 'FAIL: %, got %',label,actual;end if;return 'PASS: '||label;end;$$;
create function aroma_complaint_test.input() returns jsonb language sql immutable as $$select '{"kind":"claim","consumer":{"name":"SQL Consumer","documentType":"DNI","documentNumber":"12345678","email":"consumer@example.invalid","phone":"999888777","address":"SQL address, Lima","minor":false,"guardianName":"","guardianDocument":""},"purchase":{"kind":"product","description":"SQL fragrance","amountCents":5000,"orderReference":""},"detail":"The package arrived damaged.","request":"Please review the delivery."}'::jsonb$$;
grant execute on all functions in schema aroma_complaint_test to anon,authenticated,service_role;
insert into auth.users(id,email) values('f1000000-0000-4000-8000-000000000001','complaint-admin@example.invalid'),('f1000000-0000-4000-8000-000000000002','complaint-customer@example.invalid');
insert into private.admin_memberships(user_id,active) values('f1000000-0000-4000-8000-000000000001',true);
select aroma_complaint_test.ok((select not(rolcanlogin or rolinherit or rolbypassrls or rolsuper) from pg_roles where rolname='aro_complaints_executor'),'Complaint executor cannot login or bypass RLS');
select aroma_complaint_test.ok(not has_table_privilege('anon','app.complaints','select,insert,update,delete') and not has_table_privilege('authenticated','app.complaints','select,insert,update,delete'),'Browser roles have no direct complaint CRUD');
select aroma_complaint_test.ok(not has_table_privilege('service_role','app.complaints','select,insert,update,delete'),'Server service cannot bypass command-specific table privileges');
set local role anon;
select aroma_complaint_test.error('select api.create_complaint(''f2000000-0000-4000-8000-000000000001'',repeat(''a'',64),aroma_complaint_test.input(),repeat(''b'',64))','42501','Anonymous cannot bypass Worker submission');
select aroma_complaint_test.error('select api.admin_complaints()','42501','Anonymous cannot read complaint PII');
reset role;
set local role service_role;
select aroma_complaint_test.ok(api.create_complaint('f2000000-0000-4000-8000-000000000001',repeat('a',64),aroma_complaint_test.input(),repeat('b',64))->>'status'='received','Server registers a complaint');
select aroma_complaint_test.ok(api.create_complaint('f2000000-0000-4000-8000-000000000001',repeat('a',64),aroma_complaint_test.input(),repeat('b',64))->'history'='[]'::jsonb,'Public receipt omits administrator history');
select aroma_complaint_test.error('select api.create_complaint(''f2000000-0000-4000-8000-000000000001'',repeat(''c'',64),aroma_complaint_test.input(),repeat(''b'',64))','PT409','Another receipt secret cannot retrieve prior PII');
select aroma_complaint_test.error('select api.create_complaint(''f2000000-0000-4000-8000-000000000001'',repeat(''a'',64),jsonb_set(aroma_complaint_test.input(),''{detail}'',''"Other content"''),repeat(''b'',64))','PT409','A retry cannot replace the original complaint');
select aroma_complaint_test.error('select api.create_complaint(''f2000000-0000-4000-8000-000000000002'',repeat(''a'',64),jsonb_set(aroma_complaint_test.input(),''{consumer,minor}'',''true''),repeat(''b'',64))','22023','A minor requires guardian identification');
select aroma_complaint_test.error('select api.create_complaint(''f2000000-0000-4000-8000-000000000002'',repeat(''a'',64),jsonb_set(aroma_complaint_test.input(),''{consumer,documentNumber}'',''"123"''),repeat(''b'',64))','22023','DNI validation is enforced on server');
select aroma_complaint_test.error('select api.create_complaint(''f2000000-0000-4000-8000-000000000002'',repeat(''a'',64),jsonb_set(aroma_complaint_test.input(),''{kind}'',''null''),repeat(''b'',64))','22023','Null category cannot bypass validation');
reset role;
select aroma_complaint_test.ok((select count(*)=1 from app.complaints where operation_id='f2000000-0000-4000-8000-000000000001'),'Retries create only one row');
select aroma_complaint_test.ok((select receipt_hash<>repeat('a',64) and receipt_hash=private.commerce_hash(repeat('a',64)) from app.complaints where operation_id='f2000000-0000-4000-8000-000000000001'),'Only hashed receipt proof is stored');
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000001","aal":"aal1"}',true);
set local role authenticated;
select aroma_complaint_test.error('select api.admin_complaints()','42501','Admin AAL1 cannot read complaints');
reset role;
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000002","aal":"aal2"}',true);
set local role authenticated;
select aroma_complaint_test.error('select api.admin_complaints()','42501','Customer with AAL2 is not an administrator');
reset role;
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000001","aal":"aal2"}',true);
set local role authenticated;
select aroma_complaint_test.ok((api.admin_complaints(1,20,'received','SQL Consumer')->>'total')::int>=1,'Admin can search and filter complaints');
select aroma_complaint_test.error('select api.admin_complaints(1,101)','22023','Administrative pages are bounded');
select aroma_complaint_test.ok(api.admin_update_complaint((api.admin_complaints(1,20,'received','SQL Consumer')->'items'->0->>'id')::uuid,1,'reviewing')->>'status'='reviewing','Administrator can begin attention');
select aroma_complaint_test.error('select api.admin_update_complaint((api.admin_complaints(1,20,''reviewing'',''SQL Consumer'')->''items''->0->>''id'')::uuid,1,''responded'',''A response'',''letter'',now(),''Delivered by courier'')','PT409','Concurrent stale update is rejected');
select aroma_complaint_test.error('select api.admin_update_complaint((api.admin_complaints(1,20,''reviewing'',''SQL Consumer'')->''items''->0->>''id'')::uuid,2,''responded'',''A response'',''letter'',now(),'''')','22023','Responded requires actual delivery evidence');
select aroma_complaint_test.ok(api.admin_update_complaint((api.admin_complaints(1,20,'reviewing','SQL Consumer')->'items'->0->>'id')::uuid,2,'responded','Written resolution delivered to the consumer.','letter',now(),'SQL delivery fixture')->>'status'='responded','Written delivered response can be recorded');
select aroma_complaint_test.error('select api.admin_update_complaint((api.admin_complaints(1,20,''responded'',''SQL Consumer'')->''items''->0->>''id'')::uuid,3,''reviewing'')','22023','Delivered response cannot be overwritten or reopened silently');
select aroma_complaint_test.ok((api.admin_complaints(1,20,'responded','SQL Consumer')->'items'->0->'history'->2->>'actorId')='f1000000-0000-4000-8000-000000000001','History preserves the responsible Auth UUID');
reset role;
set local role service_role;
do $$declare i int;begin for i in 2..5 loop perform api.create_complaint(('f2000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,repeat('a',64),aroma_complaint_test.input(),repeat('b',64));end loop;end $$;
select aroma_complaint_test.error('select api.create_complaint(''f2000000-0000-4000-8000-000000000006'',repeat(''a'',64),aroma_complaint_test.input(),repeat(''b'',64))','PT429','Durable submission rate limit rejects excess records');
reset role;
rollback;
